#!/usr/bin/env python3
from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one anchor, found {count}")
    return text.replace(old, new, 1)


root = Path(__file__).resolve().parents[2]
path = root / "src/frontend/parser_statement.c"
text = path.read_text()

old = '''static bool parse_zero_aggregate_initializer(MinicParser *parser,\n                                             MinicSourceSpan *initializer_span) {\n    MinicSourcePosition begin;\n    bool saw_value;\n\n    if (parser == NULL || initializer_span == NULL || parser->current.kind != MINIC_TOKEN_LBRACE) {\n        minic_parser_error(parser, "expected aggregate zero initializer");\n        return false;\n    }\n    begin = parser->current.span.begin;\n    saw_value = false;\n    if (!minic_parser_advance(parser)) {\n        return false;\n    }\n    for (;;) {\n        if (parser->current.kind == MINIC_TOKEN_RBRACE) {\n            if (!saw_value) {\n                minic_parser_error(parser, "empty aggregate initializer is unsupported");\n                return false;\n            }\n            initializer_span->begin = begin;\n            initializer_span->end = parser->current.span.end;\n            return minic_parser_advance(parser);\n        }\n        if (parser->current.kind == MINIC_TOKEN_LBRACE) {\n            MinicSourceSpan nested_span;\n\n            if (!parse_zero_aggregate_initializer(parser, &nested_span)) {\n                return false;\n            }\n        } else {\n            MinicExpressionId value_id;\n\n            if (!minic_parser_parse_expression(parser, &value_id, 0U) ||\n                !aggregate_expression_is_zero_constant(parser->program, value_id)) {\n                if (parser->diagnostic != NULL && parser->diagnostic->message[0] == '\\0') {\n                    minic_parser_error(parser,\n                                       "only all-zero aggregate initializers are supported");\n                }\n                return false;\n            }\n        }\n        saw_value = true;\n        if (parser->current.kind == MINIC_TOKEN_COMMA) {\n            if (!minic_parser_advance(parser)) {\n                return false;\n            }\n            continue;\n        }\n        if (parser->current.kind != MINIC_TOKEN_RBRACE) {\n            minic_parser_error(parser, "expected ',' or '}' in aggregate initializer");\n            return false;\n        }\n    }\n}\n'''
new = '''static bool parse_zero_aggregate_initializer_contents(MinicParser *parser,\n                                                      MinicSourcePosition begin,\n                                                      MinicSourceSpan *initializer_span) {\n    bool saw_value;\n\n    if (parser == NULL || initializer_span == NULL) {\n        return false;\n    }\n    saw_value = false;\n    for (;;) {\n        if (parser->current.kind == MINIC_TOKEN_RBRACE) {\n            if (!saw_value) {\n                minic_parser_error(parser, "empty aggregate initializer is unsupported");\n                return false;\n            }\n            initializer_span->begin = begin;\n            initializer_span->end = parser->current.span.end;\n            return minic_parser_advance(parser);\n        }\n        if (parser->current.kind == MINIC_TOKEN_LBRACE) {\n            MinicSourcePosition nested_begin;\n            MinicSourceSpan nested_span;\n\n            nested_begin = parser->current.span.begin;\n            if (!minic_parser_advance(parser) ||\n                !parse_zero_aggregate_initializer_contents(parser, nested_begin, &nested_span)) {\n                return false;\n            }\n        } else {\n            MinicExpressionId value_id;\n\n            if (!minic_parser_parse_expression(parser, &value_id, 0U) ||\n                !aggregate_expression_is_zero_constant(parser->program, value_id)) {\n                if (parser->diagnostic != NULL && parser->diagnostic->message[0] == '\\0') {\n                    minic_parser_error(parser,\n                                       "only all-zero aggregate initializers are supported");\n                }\n                return false;\n            }\n        }\n        saw_value = true;\n        if (parser->current.kind == MINIC_TOKEN_COMMA) {\n            if (!minic_parser_advance(parser)) {\n                return false;\n            }\n            continue;\n        }\n        if (parser->current.kind != MINIC_TOKEN_RBRACE) {\n            minic_parser_error(parser, "expected ',' or '}' in aggregate initializer");\n            return false;\n        }\n    }\n}\n\nstatic bool parse_zero_aggregate_initializer(MinicParser *parser,\n                                             MinicSourceSpan *initializer_span) {\n    MinicSourcePosition begin;\n\n    if (parser == NULL || initializer_span == NULL || parser->current.kind != MINIC_TOKEN_LBRACE) {\n        minic_parser_error(parser, "expected aggregate zero initializer");\n        return false;\n    }\n    begin = parser->current.span.begin;\n    return minic_parser_advance(parser) &&\n           parse_zero_aggregate_initializer_contents(parser, begin, initializer_span);\n}\n'''
text = replace_once(text, old, new, "zero-aggregate-contents")

anchor = '''static bool add_record_copy_assignments(MinicParser *parser,\n                                        MinicExpressionId target_id,\n                                        MinicExpressionId source_id,\n                                        MinicSourceSpan span);\n\nstatic bool\nparse_local_declarator(MinicParser *parser, MinicType base_type, bool is_register_storage) {\n'''
replacement = '''static bool add_record_copy_assignments(MinicParser *parser,\n                                        MinicExpressionId target_id,\n                                        MinicExpressionId source_id,\n                                        MinicSourceSpan span);\n\nstatic bool parse_local_designated_record_initializer(MinicParser *parser,\n                                                      MinicExpressionId target_id) {\n    MinicSourceSpan initializer_span;\n    MinicSourceSpan zero_span;\n\n    if (parser == NULL || parser->current.kind != MINIC_TOKEN_LBRACE) {\n        return false;\n    }\n    zero_span = parser->current.span;\n    initializer_span.begin = parser->current.span.begin;\n    if (!minic_parser_advance(parser)) {\n        return false;\n    }\n    if (parser->current.kind != MINIC_TOKEN_DOT) {\n        return parse_zero_aggregate_initializer_contents(\n            parser, initializer_span.begin, &initializer_span) &&\n               add_zero_initialized_record_lvalue(parser, target_id, initializer_span);\n    }\n    if (!add_zero_initialized_record_lvalue(parser, target_id, zero_span)) {\n        return false;\n    }\n\n    for (;;) {\n        MinicExpressionId member_id;\n        MinicExpressionId value_id;\n        const MinicExpression *member;\n        const MinicExpression *value;\n        MinicStatement statement;\n\n        if (parser->current.kind != MINIC_TOKEN_DOT ||\n            !minic_parser_parse_direct_member(parser, target_id, &member_id) ||\n            !minic_parser_expect(parser, MINIC_TOKEN_EQUAL, "expected '=' after record designator") ||\n            !minic_parser_parse_expression(parser, &value_id, 0U)) {\n            if (parser->diagnostic != NULL && parser->diagnostic->message[0] == '\\0') {\n                minic_parser_error(parser, "expected designated record initializer");\n            }\n            return false;\n        }\n        member = minic_c0_program_expression(parser->program, member_id);\n        if (member == NULL || member->value_category != MINIC_VALUE_LVALUE ||\n            !apply_assignment_conversion(parser, member->type, &value_id) ||\n            !minic_c0_assignment_compatible(parser->program, member->type, value_id)) {\n            minic_parser_error(parser, "record designated initializer type mismatch");\n            return false;\n        }\n        value = minic_c0_program_expression(parser->program, value_id);\n        if (value == NULL) {\n            minic_parser_error(parser, "invalid record designated initializer value");\n            return false;\n        }\n\n        (void)memset(&statement, 0, sizeof(statement));\n        statement.kind = MINIC_STATEMENT_ASSIGN;\n        statement.span.begin = member->span.begin;\n        statement.span.end = value->span.end;\n        statement.target_expression = member_id;\n        statement.expression = value_id;\n        statement.target_statement = MINIC_STATEMENT_INVALID;\n        statement.then_block = MINIC_BLOCK_INVALID;\n        statement.else_block = MINIC_BLOCK_INVALID;\n        if (!minic_parser_add_statement(parser, &statement)) {\n            return false;\n        }\n\n        if (parser->current.kind == MINIC_TOKEN_COMMA) {\n            if (!minic_parser_advance(parser)) {\n                return false;\n            }\n            if (parser->current.kind == MINIC_TOKEN_RBRACE) {\n                initializer_span.end = parser->current.span.end;\n                return minic_parser_advance(parser);\n            }\n            continue;\n        }\n        if (parser->current.kind != MINIC_TOKEN_RBRACE) {\n            minic_parser_error(parser, "expected ',' or '}' in designated record initializer");\n            return false;\n        }\n        initializer_span.end = parser->current.span.end;\n        return minic_parser_advance(parser);\n    }\n}\n\nstatic bool\nparse_local_declarator(MinicParser *parser, MinicType base_type, bool is_register_storage) {\n'''
text = replace_once(text, anchor, replacement, "local-designated-record-helper")

old = '''            if (parser->current.kind == MINIC_TOKEN_LBRACE) {\n                MinicSourceSpan initializer_span;\n\n                return parse_zero_aggregate_initializer(parser, &initializer_span) &&\n                       add_zero_initialized_record_lvalue(parser, target_id, initializer_span);\n            } else {\n'''
new = '''            if (parser->current.kind == MINIC_TOKEN_LBRACE) {\n                return parse_local_designated_record_initializer(parser, target_id);\n            } else {\n'''
text = replace_once(text, old, new, "local-record-brace-dispatch")
path.write_text(text)

path = root / "tests/compiler/c0/record_local_initializer.c"
path.write_text('''struct Packet {\n    int tag;\n    unsigned char bytes[4];\n};\n\nstruct Guard {\n    void *lock;\n    int flags;\n};\n\nstatic int copy_packet(struct Packet *source) {\n    struct Packet saved = *source;\n    return saved.tag;\n}\n\nstatic int initialize_guard(void) {\n    struct Guard guard = { .lock = (void *)1, .flags = 7 };\n    return (unsigned long)guard.lock == 1 && guard.flags == 7;\n}\n\nint main(void) {\n    return initialize_guard() ? 0 : 1;\n}\n''')

path = root / "tests/compiler/c0/run-record-local-initializers.sh"
text = path.read_text()
text = replace_once(
    text,
    '''grep -F '.type copy_packet, @function' "$work/record_local_initializer.s" >/dev/null\ngrep -F '  lbu t0, 0(t2)' "$work/record_local_initializer.s" >/dev/null\ngrep -F '  sb t0, 0(t3)' "$work/record_local_initializer.s" >/dev/null\nprintf '%s\\n' 'PASS compiler/c0/record_local_initializer source=dereference whole-record-copy=yes'\n''',
    '''grep -F '.type copy_packet, @function' "$work/record_local_initializer.s" >/dev/null\ngrep -F '.type initialize_guard, @function' "$work/record_local_initializer.s" >/dev/null\ngrep -F '  lbu t0, 0(t2)' "$work/record_local_initializer.s" >/dev/null\ngrep -F '  sb t0, 0(t3)' "$work/record_local_initializer.s" >/dev/null\nprintf '%s\\n' 'PASS compiler/c0/record_local_initializer source=dereference whole-record-copy=yes designated=pointer+integer zero-fill=unspecified member-selector=shared'\n''',
    "record-local-designated-gate",
)
path.write_text(text)
